function v17Fill(exam,target,maker){let i=0,guard=0;while(PRO_BANK[exam].length<target&&guard<target*5){const q=maker(i++);if(q&&!PRO_BANK[exam].some(x=>x.id===q.id))PRO_BANK[exam].push(q);guard++}}
