function v17BalanceAnswerPositions(bank){
  bank.forEach((q,idx)=>{
    if(!q||!Array.isArray(q.choices)||q.choices.length!==4||!Array.isArray(q.why)||q.why.length!==4)return;
    const shift=idx%4;
    if(!shift)return;
    const items=q.choices.map((choice,i)=>({choice,why:q.why[i],correct:i===q.a}));
    const rotated=items.slice(-shift).concat(items.slice(0,-shift));
    q.choices=rotated.map(x=>x.choice);q.why=rotated.map(x=>x.why);q.a=rotated.findIndex(x=>x.correct);
  });
}
v17BalanceAnswerPositions(PRO_BANK.SAT);v17BalanceAnswerPositions(PRO_BANK.ACT);v17BalanceAnswerPositions(PRO_BANK.TSIA2);

function v17QualityAudit(bank,exam){const issues=[];const ids=new Set();for(const q of bank){if(!q||!q.id||ids.has(q.id)){issues.push([q?.id,'duplicate/missing id']);continue}ids.add(q.id);if(!q.section||!q.skill||!['Easy','Medium','Hard'].includes(q.difficulty))issues.push([q.id,'metadata']);if(!q.q||!Array.isArray(q.choices)||q.choices.length!==4||new Set(q.choices.map(String)).size!==4)issues.push([q.id,'choices']);if(!Number.isInteger(q.a)||q.a<0||q.a>3)issues.push([q.id,'answer']);if(!q.ex||q.ex.length<12)issues.push([q.id,'explanation']);if(!Array.isArray(q.why)||q.why.length!==4||q.why.some(x=>!x||x.length<3))issues.push([q.id,'why']);if(!q.strategy||q.strategy.length<8)issues.push([q.id,'strategy']);}return issues}
