function blueprintDomain(exam,q){
 const s=q.skill||'',sec=q.section||'';
 if(exam==='SAT') return SCOREPATH_BLUEPRINT.SAT.domains.includes(s)?s:null;
 if(exam==='ACT'){
  if(sec==='English'){
   if(/Organization|Rhetoric|Production/i.test(s))return 'Production of Writing';
   if(/Language|Style|Conciseness|Word Choice/i.test(s))return 'Knowledge of Language';
   if(/Grammar|Usage|Punctuation|Conventions/i.test(s))return 'Conventions of Standard English';
  }
  if(sec==='Math'){
   if(/Number|Quantity/i.test(s))return 'Number & Quantity';
   if(/Algebra/i.test(s))return 'Algebra';
   if(/Function/i.test(s))return 'Functions';
   if(/Geometry|Trig/i.test(s))return 'Geometry';
   if(/Statistic|Probability/i.test(s))return 'Statistics & Probability';
   if(/Integrating|Essential/i.test(s))return 'Integrating Essential Skills';
   if(/Model/i.test(s))return 'Modeling';
  }
  if(sec==='Reading'){
   if(/Main Idea|Inference|Key Ideas|Detail/i.test(s))return 'Key Ideas & Details';
   if(/Craft|Structure|Vocabulary|Author/i.test(s))return 'Craft & Structure';
   if(/Integration|Knowledge|Evidence/i.test(s))return 'Integration of Knowledge & Ideas';
  }
  if(sec==='Science (Optional)'){
   if(/Data|Interpret/i.test(s))return 'Interpretation of Data';
   if(/Experiment|Investigation|Design/i.test(s))return 'Scientific Investigation';
   if(/Model|Inference|Argument|Evidence/i.test(s))return 'Evaluating Scientific Arguments and Models with Evidence';
  }
  return null;
 }
 if(exam==='TSIA2'){
  if(sec==='Mathematics'){
   if(/Quantitative/i.test(s))return 'Quantitative Reasoning';
   if(/Algebraic/i.test(s))return 'Algebraic Reasoning';
   if(/Geometric|Spatial/i.test(s))return 'Geometric and Spatial Reasoning';
   if(/Probabilistic|Statistical/i.test(s))return 'Probabilistic and Statistical Reasoning';
  }
  if(sec==='ELAR'){
   if(/Literary/i.test(s))return 'Literary Text Analysis';
   if(/Main Idea|Inference|Vocabulary|Author|Informational/i.test(s))return 'Informational Text Analysis and Synthesis';
   if(/Revision|Organization/i.test(s))return 'Essay Revision and Editing';
   if(/Sentence|Grammar|Usage|Editing|Transition/i.test(s))return 'Sentence Revision, Editing, and Completion';
  }
  return null;
 }
 return null;
}
function validatePracticeItem(exam,q){
 const bp=SCOREPATH_BLUEPRINT[exam];
 if(!q||!bp||!bp.sections.includes(q.section))return false;
 if(!Array.isArray(q.choices)||q.choices.length!==4||!Number.isInteger(q.a)||q.a<0||q.a>3)return false;
 if(!q.q||!q.ex||!Array.isArray(q.why)||q.why.length!==4||!q.strategy)return false;
 const d=blueprintDomain(exam,q);if(!d)return false;
 q.blueprintDomain=d;q.contentOrigin='ScorePath original — official-blueprint aligned';q.blueprintVerified=true;
 return true;
}
function O(id,section,skill,difficulty,q,choices,a,ex,why,strategy,extra={}){return {id,section,skill,difficulty,q,choices,a,ex,why,strategy,...extra}}

