/* ---------- Persist generated questions so mistake/bookmark review survives reload ---------- */
function cacheSet(storeObj,set){if(!storeObj||!set)return;storeObj.questionCache=storeObj.questionCache||{};set.forEach(q=>{storeObj.questionCache[q.id]=cloneQ(q)});const keys=Object.keys(storeObj.questionCache);if(keys.length>350)keys.slice(0,keys.length-350).forEach(k=>delete storeObj.questionCache[k])}
function lookupQ(storeObj,base,id){return (base||[]).find(q=>q.id===id)||(storeObj.questionCache||{})[id]||null}
const oldShowSATListV3=showSATList;showSATList=function(type){satHideAll();$v3('satListPanel').classList.add('show');const ids=type==='mistakes'?satStore.mistakes:satStore.bookmarks;$v3('satListTitle').textContent=type==='mistakes'?'My SAT Mistakes':'Saved SAT Questions';$v3('satListIntro').textContent=type==='mistakes'?'Incorrect SAT questions stay here until mastered in later practice.':'Questions you bookmarked for focused review.';$v3('satSavedList').innerHTML=ids.length?ids.map(id=>{const q=lookupQ(satStore,PRO_BANK.SAT,id);return q?`<div class="reviewCard"><b>${q.id} — ${q.skill}</b><p>${q.q}</p></div>`:''}).join(''):`<div class="reviewCard"><b>No questions here yet.</b></div>`;$v3('satPracticeSavedBtn').dataset.type=type};
const oldShowACTListV3=showACTList;showACTList=function(type){actHideAll();$v3('actListPanel').classList.add('show');const ids=type==='mistakes'?actStore.mistakes:actStore.bookmarks;$v3('actListTitle').textContent=type==='mistakes'?'My ACT Mistakes':'Saved ACT Questions';$v3('actListIntro').textContent=type==='mistakes'?'Incorrect ACT questions stay here until mastered in later practice.':'Questions you bookmarked for focused review.';$v3('actSavedList').innerHTML=ids.length?ids.map(id=>{const q=lookupQ(actStore,PRO_BANK.ACT,id);return q?`<div class="reviewCard"><b>${q.id} — ${q.skill}</b><p>${q.q}</p></div>`:''}).join(''):`<div class="reviewCard"><b>No questions here yet.</b></div>`;$v3('actPracticeSavedBtn').dataset.type=type};

