/* ---------- Full Digital SAT adaptive controller ---------- */
let satAdaptive=null;
function routeLabel(acc){return acc>=70?'Higher-Difficulty Route':'Foundational/Mixed Route'}
/* ---------- V22: blueprint-proportional sampling for full/adaptive test modules ----------
 * Domain-weight approximations, checked against primary sources (not guessed):
 * - SAT Reading & Writing / Math: College Board, "Assessment Framework for
 *   the Digital SAT Suite" v3.01 (Aug 2024), Tables 10 & 16 — College Board's
 *   own figures are printed with "≈", i.e. these are official approximate
 *   splits, not exact integer percentages.
 * - ACT (current Enhanced ACT, 2025+): ACT Education Corp., "Comparison of
 *   the Legacy and Enhanced ACT Test Total Test and Reporting Categories"
 *   (MR038103, 2025) — midpoints of ACT's own published Enhanced-ACT ranges.
 *   Math's cross-cutting "Modeling" category is intentionally left out of
 *   this split: ACT's own document describes Modeling items as also
 *   counting toward one of the other Math categories, not a separate slice.
 * - TSIA2 Mathematics / ELAR: THECB/College Board, "TSIA2 Mathematics Test
 *   Specifications" and "TSIA2 ELAR Test Specifications", v1.4 (Jan 2021) —
 *   the CRC-form's own official item counts per domain (exact, not derived).
 * These weights only shape how ScorePath samples its OWN original practice
 * questions across the domains it already tags each item with
 * (blueprintDomain, above) — they never affect scoring and are never used
 * to claim or imply an official score. */
const SCOREPATH_BLUEPRINT_WEIGHTS={
 SAT:{
  'Reading & Writing':{'Information & Ideas':.26,'Craft & Structure':.28,'Expression of Ideas':.20,'Standard English Conventions':.26},
  'Math':{'Algebra':.35,'Advanced Math':.35,'Problem-Solving & Data Analysis':.15,'Geometry & Trigonometry':.15}
 },
 ACT:{
  'English':{'Production of Writing':.40,'Knowledge of Language':.20,'Conventions of Standard English':.40},
  'Math':{'Number & Quantity':.11,'Algebra':.19,'Functions':.19,'Geometry':.19,'Statistics & Probability':.13,'Integrating Essential Skills':.19},
  'Reading':{'Key Ideas & Details':.48,'Craft & Structure':.30,'Integration of Knowledge & Ideas':.22},
  'Science (Optional)':{'Interpretation of Data':.42,'Scientific Investigation':.24,'Evaluating Scientific Arguments and Models with Evidence':.34}
 },
 TSIA2:{
  'Mathematics':{'Quantitative Reasoning':.30,'Algebraic Reasoning':.35,'Geometric and Spatial Reasoning':.15,'Probabilistic and Statistical Reasoning':.20},
  'ELAR':{'Literary Text Analysis':.133,'Informational Text Analysis and Synthesis':.367,'Essay Revision and Editing':.133,'Sentence Revision, Editing, and Completion':.367}
 }
};
/* Largest-remainder rounding: turns fractional weight*count targets into
 * whole-number per-domain counts that always sum to exactly `count`. */
function domainTargetCounts(examKey,section,count){
 const weights=(SCOREPATH_BLUEPRINT_WEIGHTS[examKey]||{})[section];
 if(!weights)return null;
 const rows=Object.keys(weights).map(d=>({d,exact:count*weights[d]}));
 const targets={};let assigned=0;
 rows.forEach(r=>{targets[r.d]=Math.floor(r.exact);assigned+=targets[r.d]});
 let remainder=count-assigned;
 rows.sort((a,b)=>(b.exact-Math.floor(b.exact))-(a.exact-Math.floor(a.exact)));
 for(let i=0;i<remainder&&rows.length;i++)targets[rows[i%rows.length].d]++;
 return targets;
}
function pickByDifficulty(pool,count,weights){
 let picked=[];
 for(const d of ['Easy','Medium','Hard']){const want=Math.round(count*weights[d]);picked.push(...secureShuffle(pool.filter(q=>q.difficulty===d&&!picked.includes(q))).slice(0,want))}
 if(picked.length<count)picked.push(...secureShuffle(pool.filter(q=>!picked.includes(q))).slice(0,count-picked.length));
 return picked.slice(0,count);
}
function adaptivePick(pool,count,route,used,examKey,section){
 const available=pool.filter(q=>!used.has(q.id));
 const diffWeights=route==='hard'?{Easy:.15,Medium:.4,Hard:.45}:route==='foundation'?{Easy:.48,Medium:.4,Hard:.12}:{Easy:.3,Medium:.45,Hard:.25};
 const targets=(examKey&&section)?domainTargetCounts(examKey,section,count):null;
 let picked=[];
 if(targets){
  const byDomain={};Object.keys(targets).forEach(d=>byDomain[d]=[]);
  available.forEach(q=>{const d=blueprintDomain(examKey,q);if(d&&byDomain[d])byDomain[d].push(q)});
  Object.keys(targets).forEach(d=>{const got=pickByDifficulty(byDomain[d],targets[d],diffWeights);picked.push(...got.filter(q=>!picked.includes(q)))});
  if(picked.length<count){const leftover=available.filter(q=>!picked.includes(q));picked.push(...pickByDifficulty(leftover,count-picked.length,diffWeights))}
 }else{
  picked=pickByDifficulty(available,count,diffWeights);
 }
 picked=picked.slice(0,count);
 picked.forEach(q=>used.add(q.id));
 return randomizeSet(picked);
}
function satAdaptiveStageConfig(stage){return [{section:'Reading & Writing',name:'R&W Module 1',count:27,duration:32*60,route:'mixed'},{section:'Reading & Writing',name:'R&W Module 2',count:27,duration:32*60,route:satAdaptive?.rwRoute||'mixed'},{section:'Math',name:'Math Module 1',count:22,duration:35*60,route:'mixed'},{section:'Math',name:'Math Module 2',count:22,duration:35*60,route:satAdaptive?.mathRoute||'mixed'}][stage]}
function launchSATAdaptiveStage(){const cfg=satAdaptiveStageConfig(satAdaptive.stage),pool=(cfg.section==='Math'?PRO_BANK.SAT.filter(q=>q.section==='Math'):PRO_BANK.SAT.filter(q=>q.section==='Reading & Writing'));const set=adaptivePick(pool,cfg.count,cfg.route,satAdaptive.used,'SAT',cfg.section);if(set.length<cfg.count){alert('The adaptive bank could not build a complete unique module.');satAdaptive.active=false;return}cacheSet(satStore,set);saveSAT();satHideAll();$v3('satAdaptiveBreak')?.classList.remove('show');$v3('satPracticeShell').classList.add('show');satState={set,i:0,answers:{},confidence:{},flags:[],timed:true,start:Date.now(),seconds:cfg.duration,timerId:null,mode:`sat-adaptive-${satAdaptive.stage+1}`,submitted:{},duration:cfg.duration,sessionCode:sessionCode('SAT')};$v3('satTestTitle').textContent=`Digital SAT — ${cfg.name}`;$v3('satModeLabel').textContent=`Full Adaptive Simulation • Module ${satAdaptive.stage+1} of 4`;$v3('satConfidenceBox')?.classList.add('hidden');$v3('satSubmitBtn').classList.add('hidden');beginPacing('sat',satState,'satTimer',finishSAT,cfg.duration);renderSAT();location.hash='sat-center'}
function startSATAdaptive(){$v3('satAdaptiveOverall')?.remove();if(!confirm('Start the full 98-question Digital SAT practice simulation? Timers run by module and answers stay hidden until each module is submitted.'))return;satAdaptive={active:true,stage:0,used:new Set(),results:[],rwRoute:'mixed',mathRoute:'mixed',modules:[]};launchSATAdaptiveStage()}
$v3('startSatAdaptive')?.addEventListener('click',startSATAdaptive);$v3('satAdaptiveSide')?.addEventListener('click',startSATAdaptive);$v3('satAdaptiveAction')?.addEventListener('click',startSATAdaptive);
const prevSatHideV3=satHideAll;satHideAll=function(){prevSatHideV3();$v3('satAdaptiveBreak')?.classList.remove('show')};
function mergeAdaptiveModules(modules){const set=[],answers={},flags=[];modules.forEach(m=>{set.push(...m.set);Object.assign(answers,m.answers);flags.push(...m.flags)});return {set,answers,flags}}
const finishSATBeforeV3=finishSAT;finishSAT=function(auto=false){
 if(satAdaptive?.active){const cfg=satAdaptiveStageConfig(satAdaptive.stage),correct=satState.set.filter(q=>satState.answers[q.id]===q.a).length,total=satState.set.length,accuracy=pct(correct,total),elapsed=Math.max(0,satState.duration-satState.seconds),isFinal=satAdaptive.stage===3;satAdaptive.modules.push({set:satState.set,answers:{...satState.answers},flags:[...satState.flags]});cacheSet(satStore,satState.set);const thisModuleState=satState;if(isFinal){const priorModules=satAdaptive.modules.slice(0,-1);let priorAnswered=0,priorCorrect=0;priorModules.forEach(m=>m.set.forEach(q=>{if(m.answers[q.id]!==undefined){priorAnswered++;if(m.answers[q.id]===q.a)priorCorrect++}}));satStore.answered-=priorAnswered;satStore.correct-=priorCorrect;const merged=mergeAdaptiveModules(satAdaptive.modules),totalElapsed=satAdaptive.results.reduce((n,x)=>n+x.elapsed,0)+elapsed;satState={...thisModuleState,set:merged.set,answers:merged.answers,flags:merged.flags,duration:totalElapsed,seconds:0,mode:'sat-adaptive-full'};cacheSet(satStore,satState.set)}finishSATBeforeV3(auto);if(!isFinal)satState=thisModuleState;satAdaptive.results.push({name:cfg.name,section:cfg.section,correct,total,accuracy,elapsed,route:cfg.route});if(satAdaptive.stage===0)satAdaptive.rwRoute=accuracy>=70?'hard':'foundation';if(satAdaptive.stage===2)satAdaptive.mathRoute=accuracy>=70?'hard':'foundation';if(satAdaptive.stage<3){satAdaptive.stage++;$v3('satResults').classList.remove('show');$v3('satAdaptiveBreak').classList.add('show');const next=satAdaptiveStageConfig(satAdaptive.stage);$v3('satAdaptiveBreakTitle').textContent=`${cfg.name} complete`;$v3('satAdaptiveBreakText').innerHTML=`You answered <b>${correct} of ${total}</b> correctly (${accuracy}%). ${cfg.section==='Reading & Writing'&&satAdaptive.stage===1?`Your Reading & Writing Module 2 will use the <span class="routePill">${routeLabel(accuracy)}</span>.`:cfg.section==='Math'&&satAdaptive.stage===3?`Your Math Module 2 will use the <span class="routePill">${routeLabel(accuracy)}</span>.`:`Next: <b>${next.name}</b>.`}`;$v3('satAdaptiveBreakStats').innerHTML=`<div class="moduleBreakStat"><span>Accuracy</span><b>${accuracy}%</b></div><div class="moduleBreakStat"><span>Correct</span><b>${correct}/${total}</b></div><div class="moduleBreakStat"><span>Next</span><b>${next.name}</b></div>`;location.hash='sat-center';renderStudentHub();return}
 satAdaptive.active=false;const all=satAdaptive.results,tc=all.reduce((n,x)=>n+x.correct,0),tt=all.reduce((n,x)=>n+x.total,0),ta=all.reduce((n,x)=>n+x.elapsed,0);$v3('satResults').insertAdjacentHTML('afterbegin',`<div class="overallSummary" id="satAdaptiveOverall"><h3>98-Question Adaptive Simulation Summary</h3><div class="overallGrid"><div><span>Correct</span><b>${tc}/${tt}</b></div><div><span>Practice accuracy</span><b>${pct(tc,tt)}%</b></div><div><span>R&W route</span><b>${satAdaptive.rwRoute==='hard'?'Higher':'Foundational'}</b></div><div><span>Math route</span><b>${satAdaptive.mathRoute==='hard'?'Higher':'Foundational'}</b></div></div><p style="font-size:11px;color:#64748b;margin:10px 0 0">Practice performance only. This is not an official SAT score conversion. The full review and mistake list below cover all 98 questions across every module.</p></div>`);renderStudentHub();return
 }
 cacheSet(satStore,satState.set);finishSATBeforeV3(auto);renderStudentHub()
};
