function renderStudentHub(){if(!$v3('hubQuestions'))return;const bundles=allHistories(),q=bundles.reduce((n,b)=>n+(b.store.answered||0),0),c=bundles.reduce((n,b)=>n+(b.store.correct||0),0),sessions=bundles.reduce((n,b)=>n+(b.store.history||[]).length,0),review=bundles.reduce((n,b)=>n+(b.store.mistakes||[]).length,0),saved=bundles.reduce((n,b)=>n+(b.store.bookmarks||[]).length,0);$v3('hubQuestions').textContent=q;$v3('hubAccuracy').textContent=q?pct(c,q)+'%':'—';$v3('hubSessions').textContent=sessions;$v3('hubReview').textContent=review;$v3('hubSaved').textContent=saved;let goal=null;try{goal=JSON.parse(localStorage.getItem('scorepath_v2_goal')||'null')}catch(e){}if(goal?.goalDate){const d=new Date(goal.goalDate+'T00:00:00'),now=new Date();now.setHours(0,0,0,0);const days=Math.max(0,Math.ceil((d-now)/86400000));$v3('hubCountdown').textContent=days+' day'+(days===1?'':'s');$v3('hubGoalLabel').textContent=`${goal.goalExam||'Exam'} ${goal.goalScore&&goal.goalScore!=='your target'?'• target '+goal.goalScore:''}`}else{$v3('hubCountdown').textContent='Set a date';$v3('hubGoalLabel').textContent='Build your study path below'}const skills=aggregatedSkills();$v3('hubMastery').innerHTML=skills.length?skills.slice(0,6).map(x=>`<div class="masteryRow"><div class="masteryRowTop"><span>${x.exam} • ${x.skill}</span><span>${x.p}% (${x.t})</span></div><div class="masteryTrack"><i style="width:${x.p}%"></i></div></div>`).join(''):'<div class="progressEmpty">Complete a diagnostic to build your mastery profile.</div>';const weak=[...skills].sort((a,b)=>a.p-b.p)[0];if(weak){$v3('hubNext').innerHTML=`<div class="nextActionCard"><b>Priority: ${weak.exam} • ${weak.skill}</b><span>Your recorded accuracy is ${weak.p}% across ${weak.t} question${weak.t===1?'':'s'}. Review mistakes first, then launch a fresh focused set.</span></div>`;$v3('hubSmartPractice').dataset.exam=weak.exam}else{$v3('hubNext').innerHTML='<div class="nextActionCard"><b>Start with a diagnostic</b><span>Complete a mixed diagnostic so ScorePath can identify your first priority skill.</span></div>';$v3('hubSmartPractice').dataset.exam='SAT'}}
