 V9_ACT.push(O(`ACT-V9-SCI-${j+1}-4`,'Science (Optional)','Evaluating Scientific Arguments and Models with Evidence','Hard','Which statement is most consistent with the results?',[s.consistent,'The lowest measured result was actually the highest.','All tested conditions produced exactly the same outcome.','No comparison among conditions is possible.'],0,s.consistent,['Matches the reported measurements.','Reverses the data.','Contradicted by differing values.','The values can be compared.'],'Match the claim precisely to the data.',{passage:s.txt}));
