for(let i=1;i<=20;i++){const w=Math.floor((i-1)/4),x=2+w%8,kind=i%4;let q;if(kind===0){const p=20+w*5,total=100+i*5,ans=total*p/100;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Quantitative Reasoning','Medium',`What is ${p}% of ${total}?`,[String(ans),String(total-p),String(p),String(total)],0,`Convert ${p}% to ${p/100} and multiply by ${total}: ${p/100}×${total}=${ans}.`,['Correct.','Subtracts instead of finding a percent.','Uses the percent as the count.','Uses the whole.'],'Convert percent to decimal and multiply.',{calculatorAllowed:true})}else if(kind===1){const a=2+w%5,b=3+w%4,c=a*x+b;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Algebraic Reasoning',w%3===0?'Easy':'Medium',`Solve: ${a}x+${b}=${c}.`,[String(x),String(x+1),String(x-1),String(c)],0,`Subtract ${b}, then divide by ${a}: x=${x}.`,['Correct.','Does not satisfy the equation.','Stops before dividing.','Uses the constant instead of solving.'],'Use inverse operations.',{calculatorAllowed:true})}else if(kind===2){const l=x+5,ww=x,ans=l*ww;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Geometric and Spatial Reasoning','Medium',`A rectangle measures ${l} by ${ww}. What is its area?`,[String(ans),String(2*(l+ww)),String(l+ww),String(l*l)],0,`Area=${l}×${ww}=${ans}.`,['Correct.','This is perimeter.','This adds dimensions only.','This squares only one dimension.'],'Area of a rectangle is length×width.',{calculatorAllowed:true})}else{const vals=[x,x+1,x+1,x+3,x+5],median=x+1;q=O(`TSIA2-V9-M-${i}`,'Mathematics','Probabilistic and Statistical Reasoning','Medium',`What is the median of ${vals.join(', ')}?`,[String(median),String(x),String(x+3),String(x+5)],0,`The ordered middle value is ${median}.`,['Correct.','This is below the middle.','This is above the middle.','This is the maximum.'],'Order the values and choose the middle observation.',{calculatorAllowed:true})}V9_TSI.push(q)}
