const v20StartIdx=V9_TSI.length;

// Percent
for(let i=1;i<=10;i++){const cost=15+i*6,p=10+(i%8)*5,price=Math.round(cost*(1-p/100)*100)/100,off=Math.round(cost*p/100*100)/100,added=Math.round(cost*(1+p/100)*100)/100;
V9_TSI.push(O(`TSIA2-V20-M-PCT-${i}`,'Mathematics','Quantitative Reasoning — Percent',i%3===0?'Easy':'Medium',`An item costs $${cost} and is discounted ${p}%. What is the sale price before tax?`,[`$${price}`,`$${off}`,`$${added}`,`$${cost}`],0,`Convert ${p}% to a decimal (${p/100}) and multiply by $${cost} to find the discount, then subtract from the original price: $${cost} − $${off} = $${price}.`,['Correct sale price after subtracting the discount.','This is only the discount amount, not the price paid.','This adds the discount instead of subtracting it.','This is the original price with no discount applied.'],'Find the discount amount first, then subtract it from the original price.'))}

// Proportions
for(let i=1;i<=8;i++){const a=2+(i%4);let b=3+(i%5);if(b===a)b+=1;const k=6+i,given=a*k,neededB=k*b;
V9_TSI.push(O(`TSIA2-V20-M-PROP-${i}`,'Mathematics','Quantitative Reasoning — Proportions','Medium',`A mixture uses ${a} cups of ingredient A for every ${b} cups of ingredient B. If ${given} cups of A are used, how many cups of B are needed?`,[String(neededB),String(a*b),String(Math.max(1,neededB-b)),String(given)],0,`The ratio is ${a}:${b}. Since ${given} is ${k} times ${a}, use ${k} times ${b} cups of B: ${neededB}.`,['Correct — scales the ratio by the same factor.','Multiplies the two ratio numbers directly instead of scaling.','Subtracts instead of scaling the ratio.','Repeats the amount of A instead of finding B.'],'Find the scale factor between the given amount and the ratio, then apply it to the other ingredient.'))}

// Exponents
const expBases=[2,3,5,7];
for(let i=1;i<=8;i++){const b=expBases[i%4],e1=2+(i%4),e2=1+(i%3),sum=e1+e2;
V9_TSI.push(O(`TSIA2-V20-M-EXP-${i}`,'Mathematics','Algebraic Reasoning — Exponents',i%2?'Medium':'Easy',`Simplify ${b}^${e1} · ${b}^${e2}.`,[`${b}^${sum}`,`${b}^${sum+1}`,`${b*2}^${sum}`,`${b}^${Math.abs(e1-e2)||1}`],0,`When multiplying powers with the same base, add the exponents: ${b}^${e1}·${b}^${e2}=${b}^${e1+e2}.`,['Correct — exponents add for same-base multiplication.','Adds one extra to the exponent sum from a counting slip.','Changes the base instead of keeping it the same.','Subtracts the exponents instead of adding them.'],'Same base, multiplying powers: add the exponents.'))}

// Radicals
const sq=[16,25,36,49,64,81,100,121,144,169,196,225];
for(let i=0;i<8;i++){const v=sq[i],r=Math.sqrt(v);
V9_TSI.push(O(`TSIA2-V20-M-RAD-${i+1}`,'Mathematics','Algebraic Reasoning — Radicals','Easy',`What is √${v}?`,[String(r),String(r-1),String(r+1),String(Math.round(v/2))],0,`${r}×${r}=${v}, so √${v}=${r}.`,['Correct perfect-square root.','One less than the actual root.','One more than the actual root.','Half of the number under the radical, not its square root.'],'Find the integer that, when squared, equals the given number.'))}

// Linear Equations
for(let i=1;i<=12;i++){const a=2+(i%6),x=3+(i%9),bSign=i%2===0,bVal=2+(i%7),c=bSign?a*x+bVal:a*x-bVal;
V9_TSI.push(O(`TSIA2-V20-M-LEQ-${i}`,'Mathematics','Algebraic Reasoning — Linear Equations',i%4===0?'Easy':'Medium',`Solve for x: ${a}x ${bSign?'+':'−'} ${bVal} = ${c}.`,[String(x),String(x+1),String(x-1),String(c)],0,`${bSign?`Subtract ${bVal}`:`Add ${bVal}`} from both sides, then divide by ${a}: x=${x}.`,['Correct solution.','Off by one from an arithmetic slip.','Off by one from an arithmetic slip.','Mistakes the constant on the right side for x.'],'Undo addition/subtraction first, then divide to isolate x.'))}

// Systems of Equations
for(let i=1;i<=8;i++){const coef=2+(i%4),x=2+(i%6);let y=1+(i%5);if(y===x)y+=1;const s1=x+y,s2=coef*x-y;
V9_TSI.push(O(`TSIA2-V20-M-SYS-${i}`,'Mathematics','Algebraic Reasoning — Systems of Equations','Hard',`The system x + y = ${s1} and ${coef}x − y = ${s2} has solution (x,y). What is x?`,[String(x),String(y),String(s1),String(s2)],0,`Adding the two equations eliminates y: (${coef}+1)x=${s1+s2}, so x=${x}.`,['Correct — add the equations to eliminate y.','This is the value of y, not x.','This is x + y, not x alone.','This is the constant from the second equation, not the solution for x.'],'Add the two equations so that the y-terms cancel, then solve for x.'))}

// Functions
for(let i=1;i<=10;i++){const mag=2+(i%5),coef=i%2===0?mag:-mag,cmag=1+(i%6),b=i%3===0?-cmag:cmag,xv=2+(i%7),val=coef*xv+b;
V9_TSI.push(O(`TSIA2-V20-M-FUN-${i}`,'Mathematics','Algebraic Reasoning — Functions',i%2?'Medium':'Easy',`If f(x) = ${coef}x ${b>=0?'+ '+b:'− '+Math.abs(b)}, what is f(${xv})?`,[String(val),String(coef*xv),String(coef*(xv-1)+b),String(val+b)],0,`Substitute x=${xv}: ${coef}(${xv}) ${b>=0?'+':'−'} ${Math.abs(b)} = ${val}.`,['Correct substitution and evaluation.','Leaves out the constant term.','Substitutes the wrong x-value before evaluating.','Adds the constant twice.'],'Substitute the given value for x, then apply order of operations.'))}

// Slope
const slopeM=[1,-1,2,-2,3];
for(let i=1;i<=10;i++){const x1=1+(i%5),y1=2+(i%6),dx=2+(i%4),m=slopeM[i%5],dy=m*dx,x2=x1+dx,y2=y1+dy;
V9_TSI.push(O(`TSIA2-V20-M-SLP-${i}`,'Mathematics','Algebraic Reasoning — Slope','Medium',`A line passes through (${x1},${y1}) and (${x2},${y2}). What is its slope?`,[String(m),String(-m),String(m+1),String(dy)],0,`Slope = (y2−y1)/(x2−x1) = ${dy}/${dx} = ${m}.`,['Correct slope.','Reverses the sign of the slope.','Off by one from an arithmetic slip.','Reports the change in y only, without dividing by the change in x.'],'Divide the change in y by the change in x.'))}

// Factoring Quadratics
for(let i=1;i<=8;i++){const p=2+(i%5),q=3+((i+2)%6),B=p+q,C=p*q;
V9_TSI.push(O(`TSIA2-V20-M-FAC-${i}`,'Mathematics','Algebraic Reasoning — Factoring Quadratics','Hard',`Which expression is equivalent to x² − ${B}x + ${C}?`,[`(x − ${p})(x − ${q})`,`(x + ${p})(x + ${q})`,`(x − ${p+1})(x − ${Math.max(1,q-1)})`,`(x − ${B})(x − ${C})`],0,`Find two numbers that multiply to ${C} and add to ${B}: ${p} and ${q}.`,['Correct factor pair.','Uses the wrong signs for a minus-x, plus-constant trinomial.','This factor pair does not multiply to give the correct constant term.','Mistakes the coefficients themselves for the factors.'],'Look for two numbers whose product is the constant term and whose sum is the middle coefficient.'))}

// Linear Inequalities
for(let i=1;i<=8;i++){const a=2+(i%5),target=2+(i%9),b=2+(i%4),c=a*target+b;
V9_TSI.push(O(`TSIA2-V20-M-INEQ-${i}`,'Mathematics','Algebraic Reasoning — Linear Inequalities','Medium',`Which inequality is equivalent to ${a}x + ${b} < ${c}?`,[`x < ${target}`,`x > ${target}`,`x < ${target+1}`,`x < ${c}`],0,`Subtract ${b}, then divide by ${a} (positive, so the inequality direction stays the same): x < ${target}.`,['Correct — direction is preserved since we divided by a positive number.','Flips the inequality direction without a valid reason.','Off by one from an arithmetic slip.','Forgets to subtract the constant before dividing.'],'Isolate x the same way as an equation, and only flip the inequality when dividing by a negative.'))}

// Modeling with Expressions
for(let i=1;i<=8;i++){const fixed=200+i*50,costPer=3+(i%6),price=costPer+2+(i%5),margin=price-costPer;
V9_TSI.push(O(`TSIA2-V20-M-MOD-${i}`,'Mathematics','Algebraic Reasoning — Modeling with Expressions','Hard',`A business has fixed monthly costs of $${fixed} and pays $${costPer} per item produced. It sells each item for $${price}. Which expression represents monthly profit P if x items are sold?`,[`P = ${margin}x − ${fixed}`,`P = ${price}x − ${fixed}`,`P = ${margin}x + ${fixed}`,`P = ${fixed}x − ${margin}`],0,`Profit per item is $${price}−$${costPer}=$${margin}. Total profit is ${margin}x minus the fixed cost: P = ${margin}x − ${fixed}.`,['Correct — profit per item times x, minus fixed costs.','Forgets to subtract the per-item production cost.','Adds the fixed cost instead of subtracting it.','Swaps the roles of the fixed cost and the per-item profit.'],'Find profit per item first (price minus cost), then subtract the fixed cost from the total.'))}

// Area (triangle)
for(let i=1;i<=8;i++){const h=2*(2+(i%5)),b=3+i,area=b*(h/2);
V9_TSI.push(O(`TSIA2-V20-M-AREA-${i}`,'Mathematics','Geometric and Spatial Reasoning — Area','Medium',`A triangle has base ${b} units and height ${h} units. What is its area?`,[String(area),String(b*h),String(b+h),String(Math.round(area/2))],0,`Area = ½×base×height = ½×${b}×${h} = ${area}.`,['Correct area.','Forgets the ½ factor in the triangle area formula.','Adds the dimensions instead of using the area formula.','Applies the ½ factor a second time.'],'Use A = ½ × base × height for a triangle.'))}

// Circles
for(let i=1;i<=8;i++){const r=2+i,area=r*r;
V9_TSI.push(O(`TSIA2-V20-M-CIRC-${i}`,'Mathematics','Geometric and Spatial Reasoning — Circles','Medium',`A circle has radius ${r}. What is its area?`,[`${area}π`,`${2*r}π`,`${r}π`,`${2*area}π`],0,`Area = πr² = π(${r})² = ${area}π.`,['Correct area.','Uses 2r instead of r² (resembles circumference reasoning).','Forgets to square the radius.','Doubles the correctly-squared area.'],'Use A = πr², not the circumference formula.'))}

// Pythagorean Theorem
const triples=[[3,4,5],[6,8,10],[5,12,13],[9,12,15],[8,15,17],[7,24,25],[20,21,29],[12,16,20]];
triples.forEach(([a,b,c],idx)=>{
V9_TSI.push(O(`TSIA2-V20-M-PYT-${idx+1}`,'Mathematics','Geometric and Spatial Reasoning — Pythagorean Theorem','Medium',`A right triangle has legs ${a} and ${b}. What is the hypotenuse?`,[String(c),String(a+b),String(c-1),String(a*b)],0,`c=√(${a}²+${b}²)=√(${a*a}+${b*b})=√${a*a+b*b}=${c}.`,['Correct hypotenuse.','Adds the legs directly instead of using the Pythagorean theorem.','Off by one from an arithmetic slip.','Multiplies the legs, confusing this with the area of a rectangle.'],'Use c = √(a² + b²) for the hypotenuse of a right triangle.'))});

// Similarity
for(let i=1;i<=8;i++){const s1=2+i,mult=2+(i%3),s2=s1*mult,k=1+(i%4),given=k*s1,corresponding=k*s2;
V9_TSI.push(O(`TSIA2-V20-M-SIM-${i}`,'Mathematics','Geometric and Spatial Reasoning — Similarity','Medium',`Two similar figures have corresponding sides ${s1} and ${s2}. If another side of the smaller figure is ${given}, what is the corresponding side of the larger figure?`,[String(corresponding),String(corresponding+s1),String(Math.max(1,Math.round(given*s1/s2))),String(given)],0,`The scale factor is ${s2}/${s1}=${mult}. Multiply the given side by ${mult}: ${given}×${mult}=${corresponding}.`,['Correct — applies the scale factor.','Adds an extra side length instead of scaling proportionally.','Uses the inverse of the correct scale factor.','Repeats the smaller figure’s side without scaling.'],'Set up a proportion between corresponding sides and apply the scale factor consistently.'))}

// Translations
for(let i=1;i<=8;i++){const x=(i%2===0?i:-i),y=(i%3===0?-(i+1):(i+1)),dx=2+(i%5),dy=(i%2===0)?-(1+(i%4)):(1+(i%4));
V9_TSI.push(O(`TSIA2-V20-M-TRA-${i}`,'Mathematics','Geometric and Spatial Reasoning — Translations','Medium',`Point P(${x},${y}) is translated ${dx} units horizontally and ${dy} units vertically. What is P′?`,[`(${x+dx},${y+dy})`,`(${x-dx},${y-dy})`,`(${x+dx},${y})`,`(${x},${y+dy})`],0,`Add the horizontal shift to x and the vertical shift to y: (${x}+${dx}, ${y}+${dy}) = (${x+dx},${y+dy}).`,['Correct translated point.','Subtracts the shifts instead of adding them.','Applies only the horizontal shift and forgets the vertical one.','Applies only the vertical shift and forgets the horizontal one.'],'Add the horizontal shift to the x-coordinate and the vertical shift to the y-coordinate.'))}

// Probability (spinner, expected count)
for(let i=1;i<=10;i++){const n=4+(i%6);let t=1+(i%(n-1));if(t<2)t=2;const s=n*(2+(i%4)),favorable=n-t,expected=s*favorable/n;
V9_TSI.push(O(`TSIA2-V20-M-PROB-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Probability',i%2?'Medium':'Hard',`A fair ${n}-section spinner labeled 1 through ${n} is spun ${s} times. About how many spins are expected to show a number greater than ${t}?`,[String(expected),String(s*t),String(Math.round(expected/2)),String(s)],0,`${favorable} of the ${n} sections are greater than ${t}, so the expected count is ${s}×${favorable}/${n}=${expected}.`,['Correct expected count.','Multiplies spins by the threshold number instead of dividing by the number of sections.','Halves the expected count without justification.','Reports the total number of spins, not the expected favorable count.'],'Multiply the total number of trials by the probability of the favorable outcome.'))}

// Mean
for(let i=1;i<=8;i++){const base=5+i,vals=[base,base+2,base+4,base+6,base+8],sum=vals.reduce((a,b)=>a+b,0),mean=sum/5;
V9_TSI.push(O(`TSIA2-V20-M-MEAN-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Mean','Easy',`The data set is ${vals.join(', ')}. What is the mean?`,[String(mean),String(mean+2),String(mean-2),String(sum)],0,`Sum the values (${sum}) and divide by 5: ${sum}/5=${mean}.`,['Correct mean.','Off by one data-point interval from an arithmetic slip.','Off by one data-point interval from an arithmetic slip.','Reports the sum, forgetting to divide by the number of values.'],'Add all the values, then divide by how many values there are.'))}

// Median
for(let i=1;i<=8;i++){const base=3+i,vals=[base+5,base,base+8,base+2,base+1],sorted=[...vals].sort((a,b)=>a-b),median=sorted[2];
V9_TSI.push(O(`TSIA2-V20-M-MED-${i}`,'Mathematics','Probabilistic and Statistical Reasoning — Median','Easy',`The data set is ${vals.join(', ')}. What is the median?`,[String(median),String(sorted[0]),String(sorted[4]),String(Math.round(vals.reduce((a,b)=>a+b,0)/5))],0,`Order the values: ${sorted.join(', ')}. The middle value is ${median}.`,['Correct median.','Mistakes the minimum for the median.','Mistakes the maximum for the median.','Mistakes the mean for the median.'],'Order the values from least to greatest and take the middle one.'))}

// Safety net: nudge any accidental duplicate numeric distractor (never touches index 0, the correct answer)
V9_TSI.slice(v20StartIdx).forEach(q=>{
  const seen=new Set([q.choices[0]]);
  for(let i=1;i<4;i++){
    let val=q.choices[i];
    while(seen.has(val)){
      const n=parseFloat(val);
      val=(!isNaN(n) && String(n)===val)?String(n+1):val+'*';
    }
    q.choices[i]=val;seen.add(val);
  }
});

